#!/bin/bash
# scripts/gen-dwarf-copy.sh — bpf-mlir の go/requirements/uprobe.go の uprobe の DWARF の選び (uprobeSymbol・dwarfSubprogramAt・
# dwarfSubprogramFromData — E556 / E557 の address の選び、dwarfSpelling・isChar8) を E008 の差動の oracle (test/oracle/cmd/dwarf-oracle) に写す
# (E055 — 前は手で写した dwarfParams)。unexported なので宣言の本文を source から機械的に抜く (gen-strarg-copy.sh と同じ形)。
#
#   scripts/gen-dwarf-copy.sh            # test/oracle/cmd/dwarf-oracle/uprobe_copy.go を作る
#   scripts/gen-dwarf-copy.sh --check    # 今の submodule から作ったものと file が同じか (gate)
set -euo pipefail
HERE="$(cd "$(dirname "$0")/.." && pwd)"
SRC="$HERE/third_party/bpf-mlir/go/requirements/uprobe.go"
OUT="$HERE/test/oracle/cmd/dwarf-oracle/uprobe_copy.go"
gen() {
  cat <<'H'
// Code generated by scripts/gen-dwarf-copy.sh from third_party/bpf-mlir/go/requirements/uprobe.go; DO NOT EDIT.
// (requirements の uprobe の DWARF の選びは unexported — 本文をそのまま写す)

package main

import (
	"debug/dwarf"
	"debug/elf"
	"errors"
	"fmt"
)

var _ = errors.New

H
  RE='^func (uprobeSymbol|dwarfSubprogramAt|dwarfSubprogramFromData|dwarfSpelling|isChar8)\(|^type (dwarfParam|dwarfSubprogram) ' awk '
    BEGIN { re = ENVIRON["RE"] }
    !inb && $0 ~ re { print; if ($0 ~ /[{(]$/) { inb = 1; end = ($0 ~ /\($/) ? ")" : "}" } else print ""; next }
    inb { print; if ($0 == end) { inb = 0; print "" } }
  ' "$SRC"
  # E057 (bpf-mlir E559 — 形式 18): ptr の引数の DIE を直接歩く綴り (uprobe_pointer.go)
  RE='^func dwarfPointerSpelling\(' awk '
    BEGIN { re = ENVIRON["RE"] }
    !inb && $0 ~ re { print; if ($0 ~ /[{(]$/) { inb = 1; end = ($0 ~ /\($/) ? ")" : "}" } else print ""; next }
    inb { print; if ($0 == end) { inb = 0; print "" } }
  ' "$(dirname "$SRC")/uprobe_pointer.go"
}
if [ "${1:-}" = "--check" ]; then
  cmp -s <(gen) "$OUT" || { echo "gen-dwarf-copy: $OUT が submodule の uprobe.go と合わない (scripts/gen-dwarf-copy.sh で作り直す)" >&2; exit 1; }
  echo "ok: uprobe の DWARF の選びの写しは submodule と同じ"
else
  gen > "$OUT"
fi
